 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    # The two markers sharing a row define the horizontal spine; join them,
    # then connect every other marker vertically to that spine.
    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    spine_row = max(rows, key=lambda r: len(rows[r]))
    spine_cols = rows[spine_row]
    if len(spine_cols) < 2:
        return out
    for c in range(min(spine_cols), max(spine_cols) + 1):
        if out[spine_row][c] == 0:
            out[spine_row][c] = 3
    for r, c in points:
        if r == spine_row:
            continue
        step = 1 if spine_row > r else -1
        for rr in range(r + step, spine_row, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out

